import pathlib,json,hashlib,datetime,subprocess,random,platform,shutil,os
R=pathlib.Path(__file__).resolve().parents[1];H=lambda b:hashlib.sha256(b).hexdigest();utc=lambda:datetime.datetime.now(datetime.timezone.utc).isoformat()
