 matches=[p for p in uploads if H(p.read_bytes())==e['sha256']];assert len(matches)==1,(e['source_file_id'],'byte mismatch or ambiguity');p=matches[0];b=p.read_bytes();assert len(b)==e['byte_length'] and b.startswith(b'%PDF-')
