 rec={'received_at':utc(),'source_id':e['source_file_id'],'received_filename':p.name,'ledger_filename':e['original_filename'],'received_sha256':H(b),'expected_sha256':e['sha256'],'received_bytes':len(b),'expected_bytes':e['byte_length'],'expected_pages':e['page_count'],'magic_hex':b[:8].hex(),'media_type':'application/pdf','full_digest_and_size_match':True,'filename_difference':'transport copy suffix retained without renaming original bytes','rights_basis':'contemporaneous operator authorization for private bounded evaluation','independent_external_origin':False,'historical_source_clock':e['source_clock'],'authority':'PROSPECTIVE_NONCANONICAL_ONLY','original_path':str(target.relative_to(R)),'body_extracted':False,'indexed':False};records.append(rec);event('P1_RECEIVED_ORIGINAL_BYTES',rec)
